import React from 'react';
import { Task, TomorrowPlan } from '../types';

interface NightReviewProps {
  tasks: Task[];
  tomorrowPlan: TomorrowPlan;
  setTomorrowPlan: (plan: TomorrowPlan) => void;
  onComplete: () => void;
  onClose: () => void;
  darkMode: boolean;
}

const NightReview: React.FC<NightReviewProps> = ({
  tasks,
  tomorrowPlan,
  setTomorrowPlan,
  onComplete,
  onClose,
  darkMode
}) => {
  const calculatePoints = () => {
    let totalPoints = 0;
    const isWeekday = new Date().getDay() >= 1 && new Date().getDay() <= 5;

    tasks.forEach(task => {
      if (task.completed) {
        if (task.category === 'Trading') totalPoints += 10;
        else if (task.category === 'Flutter/React') totalPoints += 10;
        else if (task.category === 'Coding/DSA') totalPoints += 8;
        else if (task.category === 'Morning Routine') totalPoints += 5;
        else if (task.category === 'Night Review') totalPoints += 5;
        else totalPoints += 3;
      } else if (task.skipped) {
        if (task.category === 'Trading') totalPoints -= 10;
        else if (task.category === 'Flutter/React') totalPoints -= 10;
        else if (task.category === 'Coding/DSA') totalPoints -= 8;
        else if (task.category === 'Morning Routine') totalPoints -= 5;
        else if (task.category === 'Night Review') totalPoints -= 5;
        else totalPoints -= 3;
      }
    });

    const allCompleted = tasks.every(task => task.completed);
    if (allCompleted) totalPoints += 20;

    const allMissed = tasks.every(task => !task.completed);
    if (allMissed) totalPoints -= 30;

    return totalPoints;
  };

  const calculateGrade = () => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage >= 90) return 'A';
    if (percentage >= 80) return 'B';
    if (percentage >= 70) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-8 max-w-2xl w-full mx-4 max-h-screen overflow-y-auto`}>
        <h2 className="text-2xl font-bold text-white mb-6">Night Review & Next Day Planner</h2>

        {/* Today's Review */}
        <div className="mb-8">
          <h3 className="text-lg font-semibold text-white mb-4">Today's Performance</h3>
          <div className="space-y-2 mb-4">
            {tasks.map(task => (
              <div key={task.id} className={`flex items-center justify-between p-3 rounded ${darkMode ? 'bg-dark-primary' : 'bg-gray-50'}`}>
                <span className="text-white">{task.title}</span>
                <span className={`px-3 py-1 rounded text-sm ${
                  task.completed ? 'bg-green-600 text-white' : 
                  task.skipped ? 'bg-yellow-600 text-white' : 
                  'bg-gray-600 text-white'
                }`}>
                  {task.completed ? 'Done' : task.skipped ? 'Skipped' : 'Pending'}
                </span>
              </div>
            ))}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
              <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Today's Score</div>
              <div className="text-2xl font-bold text-yellow-400">{calculatePoints()} points</div>
            </div>
            <div className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} p-4 rounded-lg`}>
              <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Performance Grade</div>
              <div className="text-2xl font-bold text-blue-400">{calculateGrade()}</div>
            </div>
          </div>
        </div>

        {/* Tomorrow's Plan */}
        <div className="mb-6">
          <h3 className="text-lg font-semibold text-white mb-4">Plan Tomorrow</h3>
          <div className="space-y-4">
            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                English Practice Topic
              </label>
              <input
                type="text"
                value={tomorrowPlan.englishTopic}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, englishTopic: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Business English vocabulary"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                Trading Strategy
              </label>
              <input
                type="text"
                value={tomorrowPlan.tradingStrategy}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, tradingStrategy: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Focus on support/resistance levels"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                DSA Topic/Question Set
              </label>
              <input
                type="text"
                value={tomorrowPlan.dsaTopic}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, dsaTopic: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Dynamic programming - Knapsack problems"
              />
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'} mb-2`}>
                Flutter/React Chapter/Feature
              </label>
              <input
                type="text"
                value={tomorrowPlan.flutterReactChapter}
                onChange={(e) => setTomorrowPlan({...tomorrowPlan, flutterReactChapter: e.target.value})}
                className={`w-full px-4 py-2 rounded-lg ${darkMode ? 'bg-dark-primary text-white border-dark-accent' : 'bg-white text-gray-900 border-gray-300'} border focus:ring-2 focus:ring-blue-500 focus:border-transparent`}
                placeholder="e.g., Flutter widgets - State management"
              />
            </div>
          </div>
        </div>

        <div className="flex justify-end space-x-4">
          <button
            onClick={onClose}
            className={`px-6 py-2 ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-lg transition-colors`}
          >
            Cancel
          </button>
          <button
            onClick={onComplete}
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white rounded-lg transition-colors"
          >
            Lock & Sleep
          </button>
        </div>
      </div>
    </div>
  );
};

export default NightReview;
